enum MultiAgentStudyBank {
    static let sections: [StudySection] = [
        StudySection(id: "s1", title: "The Agentic Mindset and Mental Model", color: Color(red: 0.20, green: 0.40, blue: 0.70), lightColor: Color(red: 0.90, green: 0.94, blue: 1.0), icon: "brain.head.profile.fill", objectives: [
            StudyObjective(id: "s1_o1", title: "Understand the shift from monolithic bot architecture to distributed agentic systems.", topics: [
                StudyTopic(id: "s1_o1_t1", number: 1, question: "What distinguishes a distributed agentic system from a legacy decision-tree bot?", answer: "A legacy monolithic bot operates on a rigid, linear series of pre-scripted if-then statements. Every possible path must be explicitly authored, and any deviation from the scripted flow results in failure. A distributed agentic system replaces this with a reasoning model that classifies intent probabilistically from conversational context, manages dynamic state across turns and agent boundaries, and enforces safety at the architecture level rather than through authored guardrails. The agent is inherently multi-purpose — it orchestrates intent dynamically rather than following a lookup table."),
                StudyTopic(id: "s1_o1_t2", number: 2, question: "What are the three foundational assumptions of the Agentforce agentic mindset?", answer: "Salesforce best practices define three assumptions that underpin every agentic design decision. (1) Intent classification is probabilistic, not programmatic — the reasoning model selects the correct domain based on conversational context with no deterministic lookup table. (2) State is dynamic, not pre-scripted — variables evolve across turns, subagents, and agent boundaries throughout the session. (3) Safety is enforced at the architecture level — security gates, authorization checks, and trust boundaries are implemented as runtime-enforced deterministic constructs, not as natural language instructions that rely on the model to comply."),
                StudyTopic(id: "s1_o1_t3", number: 3, question: "How does a subagent function as a finite state machine at runtime?", answer: "Each subagent in Agentforce functions as an independent finite state machine. System intelligence emerges from three elements working together: Variables (the agent's working memory — values persist across turns and subagent transitions), Instructions (the rules that govern reasoning within a single turn, re-evaluated after every action execution), and Topics/Subagents (bounded domains of expertise with defined scope). The practical consequence is that you can predict and reason about agent behavior by examining state transitions across these three elements rather than trying to follow a single linear execution path."),
            ]),
            StudyObjective(id: "s1_o2", title: "Understand the variable system taxonomy and its implications for multi-agent design.", topics: [
                StudyTopic(id: "s1_o2_t1", number: 4, question: "What are the four variable types and their mutability rules?", answer: "Salesforce defines four distinct variable types: Linked variables are read-only, populated from external context injected at session start — they cannot be set by the agent and fail silently if treated as mutable. Mutable variables are read-write, set by the agent during the session — they must be initialized with a default value or guards fail silently. Slot-fill variables are write-once per turn, with the LLM extracting values from natural speech via the '...' token — the value is only available within the current turn's slot-fill context. System variables are read-only, predefined runtime context (e.g., user input) that cannot be overridden. Understanding these distinctions is a prerequisite for multi-agent design because cross-subagent state passing depends on correct variable type selection."),
                StudyTopic(id: "s1_o2_t2", number: 5, question: "Why are uninitialized mutable variables a production risk?", answer: "Best practices require that every mutable variable be initialized with an explicit default value in the variables block. An uninitialized mutable variable returns a null-like default at runtime. This causes 'available when' guards that evaluate that variable to silently fail — the condition evaluates incorrectly, and actions that should be hidden are exposed, or actions that should be available are hidden. This class of failure produces no compile-time error, making it particularly dangerous in production. The correct pattern always declares a default: 'is_verified: mutable boolean = False' and 'order_id: mutable string = \"\"'."),
            ]),
            StudyObjective(id: "s1_o3", title: "Understand the core execution order guarantee.", topics: [
                StudyTopic(id: "s1_o3_t1", number: 6, question: "What is the deterministic-before-LLM execution contract?", answer: "The single most architecturally significant principle in Agentforce agent design is the execution order guarantee: deterministic logic executes before the LLM reasoning layer engages. Always. This is a runtime contract, not a convention or suggestion. The practical consequence is that any security gate, trust check, or guard against irreversible action must be written in deterministic syntax (->), not as natural language instructions (|). Writing a guard in natural language asks the LLM to comply. Writing it in deterministic syntax enforces compliance at the runtime level, regardless of what the user says."),
            ]),
        ]),
        StudySection(id: "s2", title: "Agent Script Syntax and the Deterministic-Reasoning Divide", color: Color(red: 0.15, green: 0.35, blue: 0.65), lightColor: Color(red: 0.90, green: 0.93, blue: 1.0), icon: "chevron.left.forwardslash.chevron.right", objectives: [
            StudyObjective(id: "s2_o1", title: "Distinguish between the two instruction operators and their processing contexts.", topics: [
                StudyTopic(id: "s2_o1_t1", number: 7, question: "What is the difference between the -> (logic) operator and the | (reasoning) operator?", answer: "Agent Script uses two operators in the reasoning.instructions block processed by entirely different systems. The -> (logic/procedural) operator executes if/else branches, run actions, set assignments, and transition calls — processed by the Agent Script runtime deterministically. The | (reasoning/declarative) operator assembles text that forms the prompt sent to the LLM — processed by the LLM model. The LLM never sees raw -> instructions. By the time the LLM receives its prompt, all conditionals have already been resolved and all variable values have already been injected by the runtime. The LLM sees only the final assembled prompt text from the | lines that matched the current state."),
                StudyTopic(id: "s2_o1_t2", number: 8, question: "How are variable values injected into LLM-facing prompt text?", answer: "Within | pipe text (LLM-facing instructions), variable values are referenced using the {!@variables.X} syntax. This signals the runtime to inject the current value of the variable before passing the text to the LLM. Using @variables.X directly in pipe text without the {!...} wrapper is a syntax error that causes silent failure — the variable name is passed as a literal string rather than its value. Correct: '| Your order {!@variables.order_id} has been updated.' Incorrect (silent failure): '| Your order @variables.order_id has been updated.'"),
            ]),
            StudyObjective(id: "s2_o2", title: "Master the instruction surface lifecycle — five distinct surfaces with distinct behaviors.", topics: [
                StudyTopic(id: "s2_o2_t1", number: 9, question: "What are the five instruction surfaces and when does each fire?", answer: "Five distinct instruction surfaces exist: (1) system.instructions (global) fires before every LLM call across all subagents — durable persona and safety rules. (2) system.instructions (subagent-level) fires only within the owning subagent and completely replaces the global block — does not merge with it. (3) before_reasoning fires once per turn before any LLM processing — pre-condition checks, mandatory data loads, auth gates. Pure -> logic only. (4) reasoning.instructions is rebuilt from scratch after every action call in the reasoning loop — current turn's objective, state injection. Supports both -> and | modes. (5) after_reasoning fires once after the reasoning loop produces a user-facing response — state cleanup, post-response transitions. Pure -> logic only."),
                StudyTopic(id: "s2_o2_t2", number: 10, question: "What is the before_reasoning block used for and what are its constraints?", answer: "The before_reasoning block executes outside the LLM reasoning loop. The LLM has no awareness of it. It fires once per turn before any LLM processing begins, making it the correct location for: mandatory data pre-loads, authorization gate checks, and routing decisions based on current variable state. Because before_reasoning is pure -> logic, it cannot contain | pipe text. It also cannot use @utils.transition — only the bare 'transition to @subagent.X' syntax is valid here. Using an 'instructions:' wrapper inside before_reasoning is a compilation error."),
                StudyTopic(id: "s2_o2_t3", number: 11, question: "What is the after_reasoning block and the mid-turn transition trap?", answer: "The after_reasoning block fires once after the reasoning loop produces a response. A critical failure mode exists: if the LLM calls a @utils.transition action mid-reasoning (before the loop completes), the after_reasoning block is completely aborted for that turn. Any logic placed exclusively in after_reasoning will silently fail in sessions where this occurs. Best practice: critical state cleanup and logging should be placed as deterministic run statements inside reasoning.instructions, not exclusively in after_reasoning. Also, transitions within after_reasoning must use bare 'transition to @subagent.X' syntax — using @utils.transition in after_reasoning causes a compile error."),
                StudyTopic(id: "s2_o2_t4", number: 12, question: "How does reasoning.instructions re-resolution work after every action?", answer: "A key runtime behavior: reasoning.instructions is rebuilt from scratch after every action execution within the reasoning loop. This means post-action checks placed at the top of the reasoning.instructions block will fire immediately when action outputs update variable values. Checks placed at the bottom may not be evaluated against the freshest state in time. Best practice: always place post-action conditional checks at the top of the reasoning.instructions block so they fire immediately on re-resolution when the relevant variable changes."),
            ]),
            StudyObjective(id: "s2_o3", title: "Correctly apply action invocation patterns.", topics: [
                StudyTopic(id: "s2_o3_t1", number: 13, question: "What is the difference between deterministic and LLM-driven action invocation?", answer: "Two action invocation patterns exist and are not interchangeable. Deterministic invocation uses 'run @actions.X' inside a -> block — the runtime executes it unconditionally when the -> line is reached. Use for must-execute logic: mandatory data loads, authorization gates. LLM-driven invocation places actions in the reasoning: actions: block — the LLM selects from its available tool list contextually. Use for conversational, optional tool selection based on user intent. An action must be explicitly wired to one of these two patterns. Referencing an action name in | pipe text without listing it properly results in silent failure — the action is never invoked."),
                StudyTopic(id: "s2_o3_t2", number: 14, question: "How does the available when guard work as a security primitive?", answer: "The 'available when' condition on an action definition is a first-class security primitive, not a soft hint. When the condition is not met, the action is completely absent from the LLM's tool list — not disabled or grayed out. The LLM cannot reference or call it because it does not exist in the LLM's available context for that turn. This means an attacker cannot prompt-inject their way into calling a hidden action. The guard is enforced at the platform level, not by asking the LLM to comply with an instruction."),
                StudyTopic(id: "s2_o3_t3", number: 15, question: "What are the @utils.transition syntax rules — where is it valid and where is it not?", answer: "@utils.transition to @subagent.X is an LLM-facing tool valid only in the reasoning: actions: block. It must never appear in before_reasoning, after_reasoning, or inside -> logic blocks. In those contexts, the correct deterministic syntax is 'transition to @subagent.X' (bare syntax, no @utils. prefix). Using @utils.transition in after_reasoning is a compile error that blocks deployment."),
            ]),
            StudyObjective(id: "s2_o4", title: "Understand variable scope lifecycle rules.", topics: [
                StudyTopic(id: "s2_o4_t1", number: 16, question: "What are the three scope contexts — @inputs, @outputs, and @variables?", answer: "Three reference contexts exist for action data, each valid in a specific scope. @inputs.X is only valid during the 'with' clause of a specific action invocation — using it in a set statement after the action completes returns null. @outputs.X is only valid in set or if statements immediately after the producing action — referencing it later returns null. @variables.X is valid anywhere after the variable has been set — referencing it before the producing action has run returns the default value. The most common mistake is attempting to capture @inputs.X in a set statement, which silently returns null because @inputs is out of scope outside the with clause."),
            ]),
        ]),
        StudySection(id: "s3", title: "Subagent Boundaries and Segmentation", color: Color(red: 0.10, green: 0.45, blue: 0.60), lightColor: Color(red: 0.90, green: 0.95, blue: 0.98), icon: "square.split.2x2.fill", objectives: [
            StudyObjective(id: "s3_o1", title: "Apply the minimalist default posture for subagent design.", topics: [
                StudyTopic(id: "s3_o1_t1", number: 17, question: "What is the default design posture for subagent complexity?", answer: "Best practices establish a clear default: start with a single-domain agentic agent. Add subagent complexity only when justified by a concrete, named requirement. Every subagent boundary introduces routing overhead, variable passing complexity, and a new class of failure modes. The correct design sequence is: single subagent first, then evaluate whether a specific trigger mandates segmentation. Not: assume segmentation is better and simplify later."),
                StudyTopic(id: "s3_o1_t2", number: 18, question: "What are the three justified triggers for subagent segmentation?", answer: "Three triggers justify introducing a subagent boundary. Trigger 1 — Instruction Overload: when instruction length has degraded reasoning fidelity to the point where the agent consistently misses rule conditions or conflates domain-specific details. The trigger is observed quality degradation, not instruction length alone. Trigger 2 — Functional Divergence: when two domains require different security guardrails, data sources, or permission levels, causing LLM context-switching overhead. Trigger 3 — Modularity and Regression Control: when different teams own different functional areas, or a given area changes frequently enough that co-location creates regression risk. Independent update cycles require isolated subagent boundaries."),
            ]),
            StudyObjective(id: "s3_o2", title: "Determine when a subagent boundary becomes an agent boundary.", topics: [
                StudyTopic(id: "s3_o2_t1", number: 19, question: "What are the three thresholds that require a full agent boundary instead of a subagent boundary?", answer: "A shared .agent file means shared deployment fate. Three conditions require a separate agent: Boundary 1 — SDLC Independence: when different development teams require independent release cadences, deployment pipelines, and rollback capabilities. Boundary 2 — Independent External Invocability: when a domain must be directly callable from external systems via its own A2A endpoint and Agent Card. Boundary 3 — Regulatory Isolation: when different domains require different data sovereignty, tenant isolation, or compliance boundaries, potentially requiring separate Salesforce orgs using MOMA."),
                StudyTopic(id: "s3_o2_t2", number: 20, question: "What are the state transfer mechanics across agent boundaries?", answer: "When state must cross an agent boundary, two transfer mechanisms exist: @utils.transition to a connected agent is a one-way handoff where the caller context is discarded after transfer — use for terminal transfers where the receiving agent owns the session going forward. @subagent.<name> (within the same agent) is a round-trip delegation where control returns to the caller after the subagent completes — use for non-terminal delegations where the calling subagent needs to act on the result. Using a terminal handoff when a round-trip is needed results in lost context and broken state continuity."),
            ]),
        ]),
        StudySection(id: "s4", title: "Multi-Agent Design Patterns", color: Color(red: 0.25, green: 0.50, blue: 0.45), lightColor: Color(red: 0.90, green: 0.96, blue: 0.95), icon: "square.3.layers.3d.top.filled", objectives: [
            StudyObjective(id: "s4_o1", title: "Compare and select from the four multi-agent design patterns.", topics: [
                StudyTopic(id: "s4_o1_t1", number: 21, question: "What is Pattern 1 — Monolithic Subagent?", answer: "All capabilities are handled in a single subagent with no routing between specialized domains. Reasoning fidelity is low due to context dilution across mixed domains. State management is simple with no cross-subagent variable passing required. SDLC risk is high because any change touches all capabilities simultaneously. Appropriate use: prototypes only — never in production for complex or mixed-domain logic."),
                StudyTopic(id: "s4_o1_t2", number: 22, question: "What is Pattern 2 — Single Agent with Intent Classifier (SOMA Light)?", answer: "A single Salesforce org hosts one agent with multiple specialized subagents. A router (typically using the EinsteinHyperClassifier) classifies intent and transitions to the appropriate subagent. Reasoning fidelity is high due to scoped, focused instructions per subagent. State management is medium — variables are shared within the same agent lifecycle. SDLC risk is medium — the entire agent is redeployed when any single subagent changes. Appropriate when one team owns all domains, updates are infrequent, and a shared org boundary is appropriate."),
                StudyTopic(id: "s4_o1_t3", number: 23, question: "What is Pattern 3 — Orchestrator to Separate Agents (SOMA/MOMA)?", answer: "Multiple separate agents with independent identities. An orchestrator agent delegates to specialist agents via agent-to-agent calls. Agents may reside in the same org (SOMA) or separate orgs (MOMA). Reasoning fidelity is maximum due to full contextual isolation per agent. State management is complex — explicit variable mapping required across agent boundaries; MOMA caps at 10 messages of context. SDLC independence is maximum — each agent has its own deployment lifecycle. Appropriate when different teams own each domain, regulatory isolation is required, or independent external API exposure is needed."),
                StudyTopic(id: "s4_o1_t4", number: 24, question: "What is Pattern 4 — Hybrid Orchestration and what is the pattern selection decision tree?", answer: "Pattern 4 combines Patterns 2 and 3. Some domains are grouped together in the same agent (sharing genuine data affinity), while others are isolated as separate agents (requiring strict independence). The pattern selection decision tree: (1) Does any domain need independent external API exposure or A2A invocability? Yes → Pattern 3 or 4. (2) Do different teams own different domains with independent release cadences? Yes → Pattern 3 or 4. (3) Do any domains require different permission boundaries? Yes → Pattern 3 or 4. (4) Would a single subagent exceed high-fidelity reasoning capacity? Yes → Pattern 2. (5) None of the above: Pattern 1 — single subagent, simplest viable architecture."),
            ]),
        ]),
        StudySection(id: "s5", title: "Deployment Patterns — SOMA, MOMA, and 3P", color: Color(red: 0.30, green: 0.55, blue: 0.40), lightColor: Color(red: 0.91, green: 0.96, blue: 0.93), icon: "building.2.fill", objectives: [
            StudyObjective(id: "s5_o1", title: "Apply SOMA architecture and understand its technical limits.", topics: [
                StudyTopic(id: "s5_o1_t1", number: 25, question: "What are the SOMA technical limits and latency profile?", answer: "Single-Org Multi-Agent (SOMA) operates within one Salesforce org. Key platform constraints: up to 7-8 subagents wide (soft limit; observability dashboard flags at 7), maximum 2 delegation levels deep (Agent A to Agent B; no tertiary Agent C), session duration of 24-48 hours maximum, bidirectional variable sync between Superagent and subagents at GA, and last 20 messages of conversation history passed on each delegation. SOMA latency profile (P95 estimates): Supervised Mode at approximately 12-20 seconds, Handoff Mode at approximately 8-14 seconds. The synthesis hop in Supervised Mode adds approximately 2-3 seconds compared to Handoff Mode."),
                StudyTopic(id: "s5_o1_t2", number: 26, question: "What are the tradeoffs between Handoff Mode and Supervised Mode?", answer: "In Supervised Mode, the Superagent synthesizes the subagent's output before responding to the user. This enables multi-intent support (Superagent can coordinate across multiple subagents) but adds latency from the synthesis hop (~2-3s). In Handoff Mode, the subagent streams directly to the user, removing the synthesis hop for lower latency but limiting to single-intent per turn. Supervised Mode is best for complex sessions requiring Superagent-level coherence. Handoff Mode is best for high-volume, latency-sensitive, single-intent interactions."),
            ]),
            StudyObjective(id: "s5_o2", title: "Apply MOMA architecture and know when it is and is not the right choice.", topics: [
                StudyTopic(id: "s5_o2_t1", number: 27, question: "When should you evaluate Data Cloud Zero-Copy Federation before choosing MOMA?", answer: "Multi-Org Multi-Agent (MOMA) is not the default choice for cross-org scenarios. Best practices require evaluating Data Cloud Zero-Copy Federation first. If the external org's data can be federated into the primary org using Zero-Copy, the data boundary concern is solved at the data layer — and a SOMA pattern with full bidirectional variable sync, no 10-message cap, and no JWT complexity can be maintained. MOMA is correct only when the concern is agent execution isolation: the secondary org requires write-backs within its own tenant boundary, regulatory requirements mandate agent logic executes within the secondary org's tenancy, the secondary org is owned by a separate business entity, or the secondary org team requires independent agent deployment governance."),
                StudyTopic(id: "s5_o2_t2", number: 28, question: "What are the MOMA hard architectural constraints?", answer: "MOMA carries constraints that cannot be configured away: delegation depth is strictly one level (Primary to Secondary; no tertiary); context cap is last 10 messages (hard limit, not configurable); memory model is pass-by-value, not shared memory; all orgs must share the same DC1 trust boundary for data sovereignty compliance; one org can belong to exactly one trust boundary to prevent cross-boundary leakage; and agents are not auto-shared across orgs — admin must explicitly mark as shareable. Additionally, identity is propagated via email-based resolution, and if it fails, the system silently defaults to Guest User — a significant permission downgrade that must be explicitly planned for."),
            ]),
            StudyObjective(id: "s5_o3", title: "Understand third-party (3P) agent interoperability.", topics: [
                StudyTopic(id: "s5_o3_t1", number: 29, question: "What are the 3P interoperability directions, auth mechanisms, and hard limits?", answer: "Third-party agent interoperability allows Agentforce to communicate with agents from other vendors via the A2A protocol. Outbound (Agentforce to third-party) uses Named Credentials + OAuth with Guest User context only (currently in Pilot). Inbound (third-party to Agentforce) uses Web-Server Flow for AEA and Client Credentials Flow for ASA (also Pilot). Hard platform limits: A2A payload must conform to the A2A protocol schema, no parallel tasks per request, plain text responses only (rich modalities planned post-Pilot), and a 15-second hard round-trip limit — any delegation with unpredictable latency must implement SSE streaming to avoid timeout failures."),
            ]),
        ]),
        StudySection(id: "s6", title: "Routing Architecture and the EinsteinHyperClassifier", color: Color(red: 0.35, green: 0.25, blue: 0.60), lightColor: Color(red: 0.93, green: 0.91, blue: 1.0), icon: "arrow.triangle.branch", objectives: [
            StudyObjective(id: "s6_o1", title: "Understand the routing stack and trust layer.", topics: [
                StudyTopic(id: "s6_o1_t1", number: 30, question: "What is the four-layer routing stack and its execution order?", answer: "Every user message passes through four processing layers in sequence. Layer 1 — Einstein Trust Layer: three built-in platform guardrails (Prompt_Injection, Inappropriate_Content, Reverse_Engineering) run before any custom logic. A BLOCK at this layer means custom agent logic never executes. Layer 2 — EinsteinHyperClassifier (when assigned as the router model): Salesforce-owned routing model optimized for intent classification, significantly faster and more accurate than general LLMs for this specific task. Routes to subagents via @utils.transition only. Layer 3 — Subagent Topic Selection (standard LLM): full before_reasoning and after_reasoning lifecycle support exists at this level. Layer 4 — Subagent Action Selection: LLM selects from the available tool list based on the assembled prompt and current context."),
                StudyTopic(id: "s6_o1_t2", number: 31, question: "What are the EinsteinHyperClassifier capabilities and hard limitations?", answer: "The EinsteinHyperClassifier is the default router model in Service Agent templates, with advantages in speed and classification accuracy. Its hard limitations are platform-enforced and cannot be configured away: it cannot use before_reasoning or after_reasoning blocks at the start_agent level, and it can only use @utils.transition as a tool — no other action types are supported. Attempting to deploy a start_agent with before_reasoning logic while the HyperClassifier is assigned causes a deployment failure."),
                StudyTopic(id: "s6_o1_t3", number: 32, question: "What is the model override trade-off for gaining lifecycle hooks?", answer: "When deterministic before_reasoning logic is needed at the router level, override the HyperClassifier with a standard LLM via model_config. The trade-off: maximum routing speed and classification accuracy requires the HyperClassifier with no lifecycle hooks. Deterministic before_reasoning gates at the router level require a standard LLM via model_config with latency and accuracy trade-offs. To achieve both speed and lifecycle hooks, use an auth gate subagent pattern: keep the HyperClassifier as router and push preconditions into the first-destination subagent's before_reasoning block."),
                StudyTopic(id: "s6_o1_t4", number: 33, question: "Why are mutually exclusive subagent descriptions critical for routing?", answer: "The EinsteinHyperClassifier treats subagent and transition action descriptions as classification boundaries. Overlapping or ambiguous descriptions produce non-deterministic routing — the same user utterance may route to different subagents across sessions. Best practices require every subagent description to be semantically mutually exclusive. Bad example: 'Handles customer payment and account questions' vs 'Handles customer account and payment issues' — these overlap. Good example: 'Processes payments, refunds, and invoice disputes' vs 'Manages profile updates, password resets, and access permissions' — these are mutually exclusive. The go_to_ prefix convention on transition actions groups them visually and signals routing intent."),
            ]),
        ]),
        StudySection(id: "s7", title: "Model Selection and the model_config Override", color: Color(red: 0.40, green: 0.30, blue: 0.55), lightColor: Color(red: 0.94, green: 0.92, blue: 1.0), icon: "cpu.fill", objectives: [
            StudyObjective(id: "s7_o1", title: "Apply model inheritance and override rules.", topics: [
                StudyTopic(id: "s7_o1_t1", number: 34, question: "What is the model configuration precedence chain?", answer: "The model used for any subagent is determined by a precedence hierarchy — most specific wins: Org-level model (configured in Setup) is overridden by Agent-level model_config (applies to all subagents), which is overridden by Subagent-level model_config (applies only to that specific subagent). Agent-level configuration is the recommended baseline; subagent-level overrides should be applied only where a specific subagent's reasoning complexity genuinely justifies a different model."),
                StudyTopic(id: "s7_o1_t2", number: 35, question: "What are the Salesforce-internal model API names and assignment strategy?", answer: "Model names in model_config blocks must use Salesforce-internal sfdc_ai__ API identifiers, not public vendor names. Key models: EinsteinHyperClassifier for router classification only; sfdc_ai__DefaultGPT41 for router override and general-purpose reasoning; sfdc_ai__DefaultBedrockAnthropicClaude45Haiku for slot-fill, lightweight subagents, and latency-sensitive tasks; sfdc_ai__DefaultVertexAIGemini35Flash for fast conversational handling. Best practices map model selection to subagent responsibility: HyperClassifier for routers, Haiku for slot-fill collectors and escalation, heavyweight models only for complex reasoning subagents. Stratifying models by type reduces P95 latency materially versus using a uniform heavyweight model at every hop."),
            ]),
        ]),
        StudySection(id: "s8", title: "State, Memory, and Context Sharing Across Boundaries", color: Color(red: 0.45, green: 0.35, blue: 0.50), lightColor: Color(red: 0.95, green: 0.93, blue: 0.97), icon: "arrow.left.arrow.right.circle.fill", objectives: [
            StudyObjective(id: "s8_o1", title: "Understand variable sync rules across SOMA, MOMA, and 3P boundaries.", topics: [
                StudyTopic(id: "s8_o1_t1", number: 36, question: "How do state sharing capabilities differ by deployment pattern?", answer: "Variable and context sharing behavior differs significantly across deployment patterns. In SOMA: mutable variable sync is bidirectional (changes in subagent reflect in Superagent when control returns), last 20 messages of conversation history are passed, and no shared persistent memory exists. In MOMA: sync is pass-by-value at delegation time only, last 10 messages (hard cap), and no shared persistent memory. In 3P: only Session ID + last 10 messages are passed, and no shared persistent memory exists. In SOMA, bidirectional sync means changes a subagent makes during its turn are reflected in the Superagent's state when control returns — a significant advantage over MOMA's pass-by-value model."),
                StudyTopic(id: "s8_o1_t2", number: 37, question: "How does variable mapping validation work at design time?", answer: "When a mutable variable that is mapped across subagents is renamed or deleted, the platform blocks the save operation at design time. This prevents silent runtime breakage in variable mappings. It is a design-time safety gate, not a runtime recovery mechanism — which means the correct practice is to maintain consistent variable names throughout the agent lifecycle and treat renames as a formal change operation."),
            ]),
        ]),
        StudySection(id: "s9", title: "Interoperability Protocols — MCP and A2A", color: Color(red: 0.50, green: 0.30, blue: 0.45), lightColor: Color(red: 0.96, green: 0.92, blue: 0.95), icon: "link.circle.fill", objectives: [
            StudyObjective(id: "s9_o1", title: "Understand the Model Context Protocol (MCP).", topics: [
                StudyTopic(id: "s9_o1_t1", number: 38, question: "What is MCP and what are the three asset categories?", answer: "The Model Context Protocol is a standardized interface for AI agents to discover and invoke capabilities across the broader AI tooling ecosystem. It defines a client-server model: the MCP Client is the agent consuming tools, prompts, and resources; the MCP Server is the host exposing them. Three asset categories can be advertised: Tools (executable functions that become callable actions for the agent's LLM), Prompts (pre-defined templates for LLM interaction), and Resources (static or dynamic data sources such as databases, APIs, and knowledge bases)."),
                StudyTopic(id: "s9_o1_t2", number: 39, question: "What is the MCP CLI workflow and what are the critical caveats?", answer: "The MCP CLI workflow has four steps: Step 1 — Register: register the server (due to a known preview bug, always verify the returned JSON immediately as --server-url may not persist). Step 2 — Fetch: read the live external MCP server to discover advertised assets (read-only, does not grant access). Step 3 — Allowlist: write the allowlist (this is a full replacement, not additive — assets omitted from the payload are silently removed; always fetch the current allowlist first). Step 4 — Verify: read the Salesforce catalog to confirm what is currently allowlisted and accessible to agents (different from fetch, which reads the live server). Security best practices: store MCP server OAuth secrets in Named Credentials, review fetch output as a security artifact before running asset replace, and audit active agent access regularly."),
            ]),
            StudyObjective(id: "s9_o2", title: "Understand the Agent-to-Agent (A2A) Protocol.", topics: [
                StudyTopic(id: "s9_o2_t1", number: 40, question: "What is the A2A four-step interaction lifecycle?", answer: "The Agent-to-Agent protocol enables Agentforce agents to communicate with agents from any vendor. The lifecycle has four steps: Step 1 — Discovery: each agent publishes an Agent Card (JSON document advertising capabilities, auth requirements, and endpoint). Step 2 — Task Delegation: tasks are requested via HTTP/JSON-RPC 2.0 as Messages containing Parts (typed parameters). Step 3 — Execution and Response: the receiving agent processes the task and returns Artifacts (structured outputs). Step 4 — Streaming Updates: real-time status streams via Server-Sent Events (SSE) or Push Notifications. SSE configuration is required for any delegation with unpredictable latency to prevent silent timeout failures at the 15-second hard limit."),
                StudyTopic(id: "s9_o2_t2", number: 41, question: "How do you choose between MCP and A2A?", answer: "The practical decision rule: if the remote system is a function (takes inputs, returns outputs, no independent reasoning), use MCP. If the remote system is an agent (interprets intent, plans its own execution, manages its own state), use A2A. Key differences: MCP connects agent to tool/resource/prompt with stateless tool calls; A2A connects agent to agent with stateful task sessions and SSE updates. MCP receivers execute functions only; A2A receivers reason, plan, and execute independently. Discovery uses fetch for MCP and Agent Cards for A2A. MuleSoft Agent Fabric acts as the broker registry for third-party agents (AWS Q, Bedrock, Azure AI Foundry, etc.) without requiring custom point-to-point integrations."),
            ]),
        ]),
        StudySection(id: "s10", title: "Trust, Security, and Identity", color: Color(red: 0.55, green: 0.20, blue: 0.35), lightColor: Color(red: 0.96, green: 0.91, blue: 0.93), icon: "shield.lefthalf.filled", objectives: [
            StudyObjective(id: "s10_o1", title: "Understand platform-level trust guardrails.", topics: [
                StudyTopic(id: "s10_o1_t1", number: 42, question: "What are the three built-in platform guardrails in the Einstein Trust Layer?", answer: "Three built-in subagents run at the platform level before any custom agent logic executes — they cannot be disabled or bypassed: Prompt_Injection (detects attempts to override agent instructions through user input), Inappropriate_Content (screens for content policy violations), and Reverse_Engineering (detects attempts to expose internal agent logic). A BLOCK-level finding from any of these prevents the custom agent from executing for that session. Safety review findings are classified at three severity levels: BLOCK (stops deployment pipeline, must be resolved), WARN (flags for human review, does not stop deployment), and INFO (best-practice recommendations)."),
                StudyTopic(id: "s10_o1_t2", number: 43, question: "Why must authorization gates be implemented as deterministic logic rather than natural language?", answer: "Authorization gates, trust checks, and guards against irreversible actions must be implemented as deterministic -> logic — not as | natural language instructions. Writing a security guard in natural language is asking the LLM to comply with it voluntarily. Writing it in deterministic -> syntax enforces compliance at the runtime level, where the LLM has no ability to override it regardless of what the user says. This is the practical application of the core architectural axiom: safety enforced at the architecture level, not by trusting the LLM."),
            ]),
            StudyObjective(id: "s10_o2", title: "Understand identity propagation across deployment patterns.", topics: [
                StudyTopic(id: "s10_o2_t1", number: 44, question: "How does the identity model differ by deployment pattern?", answer: "Identity models differ significantly by pattern. In SOMA: uniform session user across all agents in the same org — no identity failure mode. In MOMA: email-based resolver maps user across orgs without re-authentication, but fallback to Guest User occurs if email resolution fails — this is a significant permission downgrade requiring explicit planning. If a secondary org requires step-up authentication, the login prompt fires in the primary org's interface. In 3P: Session ID + JWT are used, and user identity is not automatically propagated — the third-party agent executes in its own auth context. The architectural guarantee: no agent may act outside its trust boundary or elevate privileges beyond the initiating user."),
            ]),
        ]),
        StudySection(id: "s11", title: "Governance, Observability, and Quality Assurance", color: Color(red: 0.20, green: 0.50, blue: 0.55), lightColor: Color(red: 0.90, green: 0.96, blue: 0.97), icon: "checkmark.shield.fill", objectives: [
            StudyObjective(id: "s11_o1", title: "Understand the seven-stage agent lifecycle.", topics: [
                StudyTopic(id: "s11_o1_t1", number: 45, question: "What are the seven stages of the Agentforce agent lifecycle?", answer: "The seven stages are: (1) Discover — browse and evaluate available agents via Agentforce Studio/Asset Library. (2) Register — integrate 3P agents and MCP servers via Agentforce Registry. (3) Build and Orchestrate — connect agents, configure routing, map variables via Agentforce Builder. (4) Govern — define and enforce organizational policies via Agentforce Gateway. (5) Observe and Test — monitor performance, validate functionality, trace failures via Testing Center and STDM. (6) Publish — distribute agents to internal or external marketplaces via Agent Exchange. (7) Use — deliver unified end-user experience across all channels."),
            ]),
            StudyObjective(id: "s11_o2", title: "Apply observability practices — tracing and session diagnostics.", topics: [
                StudyTopic(id: "s11_o2_t1", number: 46, question: "What is the Session Trace Data Model (STDM) and how does bidirectional trace lookup work?", answer: "Every subagent trace is persisted as an independent session trace in STDM. Discrete handoff entries are recorded in the Primary Agent's trace at every delegation. Bidirectional trace lookup is supported — Forward: Primary Agent step to Subagent session ID; Backward: Subagent session to Primary Agent ID via PreviousSessionId. This bidirectional capability is essential for diagnosing failures in multi-agent sessions where the root cause may be in a subagent trace, not the primary agent trace."),
                StudyTopic(id: "s11_o2_t2", number: 47, question: "What are the three key step types in session traces for diagnosing failures?", answer: "Session traces contain three step types mapping to different diagnostic scenarios. LLMStep: read the resolved LLM input to see exactly what prompt the model received — useful for diagnosing incorrect routing, wrong variable injection, or missing context. FunctionStep / ACTION_STEP: check preVars and postVars on action steps to see variable state before and after action execution — useful for diagnosing action failures, incorrect outputs, or missing variable updates. ReasoningStep: trace the reasoning loop to see which tools the LLM selected and in what order — useful for diagnosing unexpected action calls or missed transitions."),
            ]),
            StudyObjective(id: "s11_o3", title: "Configure and apply Custom Evaluations (LLM-as-Judge) for multi-agent QA.", topics: [
                StudyTopic(id: "s11_o3_t1", number: 48, question: "What are Custom Evaluations and how do they work for multi-agent quality assurance?", answer: "For multi-agent architectures, manual CLI tracing is necessary but not sufficient for production QA. Custom Evaluations use a secondary LLM (configured in the Testing Center) to automatically review conversation logs and score sessions against defined quality criteria without human review of every trace. They are configured with a judge model, a scope (session-level covering the full conversation log across all subagents), and specific criteria expressed as natural language questions the judge LLM answers about each session. Custom Evals can trigger post-session on all production sessions with a configurable sample rate and route flagged sessions to a QA queue."),
                StudyTopic(id: "s11_o3_t2", number: 49, question: "What is Semantic Conflict Detection and why is it critical for MOMA deployments?", answer: "In SOMA and MOMA deployments, different agents may reach logically contradictory conclusions within the same session. Neither agent makes a technical error — both make correct decisions within their own context. The conflict only becomes visible when the two agents' assertions are read together. Example: Agent A (Promotions) grants a 20% loyalty discount, but Agent B (Billing) processes the invoice without applying it. Semantic Conflict Detection is a Custom Eval pattern that scans full session logs for this class of failure. For MOMA deployments specifically — where the 10-message context cap increases the risk that agents lack full session context — Custom Evals including semantic conflict detection are a foundational quality gate, not optional."),
                StudyTopic(id: "s11_o3_t3", number: 50, question: "What is Endless Reasoning Loop Detection?", answer: "A session is in an endless reasoning loop when agents cycle without making forward progress. A judge LLM can identify these sessions by scanning for diagnostic signals: the same slot-fill question asked more than twice without a new value being captured, the same action attempted multiple times with the same inputs without a different outcome, and the user expressing the same intent in progressively more direct language without receiving resolution. Endless loop detection should be configured as a Custom Eval criterion in any production multi-agent deployment."),
            ]),
            StudyObjective(id: "s11_o4", title: "Implement the 'No Results vs. Failure' disambiguation pattern.", topics: [
                StudyTopic(id: "s11_o4_t1", number: 51, question: "Why must subagents distinguish between system failure and empty results?", answer: "Two fundamentally different runtime outcomes require two fundamentally different user messages. Every subagent that calls an external data source must implement explicit three-way branching: System Failure (timeout, platform error, or action exception) requires acknowledging the system problem explicitly and providing a concrete recovery path — never claim 'no results' when the system failed. Success — No Results (action executed successfully but returned empty) requires acknowledging the search completed successfully, confirming the parameters searched, and offering next steps — never say 'something went wrong' when nothing did. Success — Results Found presents the data and offers relevant follow-up actions. This three-way branch is a required pattern in any subagent that sources data from an external system."),
            ]),
        ]),
        StudySection(id: "s12", title: "Common Failure Modes and Pre-Deployment Checklist", color: Color(red: 0.60, green: 0.25, blue: 0.30), lightColor: Color(red: 0.97, green: 0.91, blue: 0.92), icon: "exclamationmark.triangle.fill", objectives: [
            StudyObjective(id: "s12_o1", title: "Identify and remediate common platform and compiler failures.", topics: [
                StudyTopic(id: "s12_o1_t1", number: 52, question: "What are the common compiler failures and their fixes?", answer: "Key compiler failures include: Empty reasoning block (subagent has no instructions — every subagent requires non-empty reasoning.instructions). Schema validation error (system.instructions names a capability with no corresponding subagent — every named capability must map to an actual subagent). Unresolvable action source (managed package namespace not installed — verify with agent discover before committing). @utils.transition rule violation (invalid properties like label, require_user_confirmation, or inputs on a utility action — only description and available when are valid). developer_name mismatch (config name doesn't match the directory name — exact case-sensitive match required). before_reasoning in HyperClassifier router (remove the lifecycle hook or override with model_config). @utils.transition in after_reasoning (replace with bare transition syntax)."),
            ]),
            StudyObjective(id: "s12_o2", title: "Identify and remediate common runtime and state failures.", topics: [
                StudyTopic(id: "s12_o2_t1", number: 53, question: "What is the aborted lifecycle failure and how do you prevent it?", answer: "When the LLM calls a @utils.transition action mid-reasoning, after_reasoning is aborted for that turn. State cleanup, logging, or transitions placed exclusively in after_reasoning will silently fail. The fix: move critical cleanup into deterministic run statements inside reasoning.instructions before the transition, so it executes regardless of whether after_reasoning fires."),
                StudyTopic(id: "s12_o2_t2", number: 54, question: "What are circular delegation loops and action loops?", answer: "Circular delegation occurs in non-hierarchical agent graphs where Agent A delegates to Agent B and Agent B can delegate back to Agent A, forming loops with no terminal state. These consume session resources until platform limits terminate the session. Every agent graph must be audited to confirm all delegation paths have guaranteed terminal paths — either a user response or @utils.escalate. Action loops occur when an action in reasoning.actions has no available when guard and no post-action stop condition — it is called repeatedly on every reasoning re-resolution. Every write action must have an available when guard that removes it from the tool list after its intended execution."),
            ]),
            StudyObjective(id: "s12_o3", title: "Apply the production agentic maturity roadmap.", topics: [
                StudyTopic(id: "s12_o3_t1", number: 55, question: "What are the six levels of agentic maturity?", answer: "Best practices define an incremental maturity model: Level 1 — Agent Script Mastery: deterministic -> vs reasoning |, action targets, variable scope discipline. Level 2 — Subagent Segmentation: three triggers, mutually exclusive descriptions, available when as security primitive, HyperClassifier constraints. Level 3 — Model Stratification: agent-level model_config as baseline, subagent overrides where justified, sfdc_ai__ API names, version testing. Level 4 — SOMA Orchestration: Superagent as single entry point, bidirectional variable sync, Handoff vs Supervised mode, Data Cloud Zero-Copy evaluation. Level 5 — MOMA and 3P: cross-org trust boundaries, A2A protocol, MCP tool ecosystem, MuleSoft Agent Fabric. Level 6 — Full Ecosystem Integration: multi-protocol architectures, Custom Evals (LLM-as-Judge), disambiguation patterns at scale, STDM observability, independent SDLC per domain."),
            ]),
        ]),
    ]
}
